      cm: '#6e7781',
      str: '#0a3069',
      num: '#0550ae',
      kw: '#cf222e',
      fn: '#8250df',
      type: '#953800',
      prop: '#0550ae',
      tag: '#116329',
      attr: '#0550ae',
